            "items": {
                "type": "object",
                "required": [
                    "metricName",
                    "atlasUri",
                    "account"
                ],
                "properties": {
                    "metricName": {
                        "description": "Name of the metric that will be created in CloudWatch",
                        "type": "string",
                        "pattern": "^(?:(?:[\\w\\-\\.\\s]+)|(?:\\$\\([\\w\\-\\.]+\\)))+$"
                    },
                    "atlasUri": {
                        "description": "Atlas query",
