                        "items": {
                            "type": "object",
                            "required": [
                                "name",
                                "value"
                            ],
                            "properties": {
                                "name": {
                                    "description": "Name of the CloudWatch dimension",
                                    "type": "string",
                                    "pattern": "^[\\w\\-\\.]+$"
                                },
                                "value": {
                                    "description": "Atlas tag. Example: $(nf.asg)",
                                    "type": "string",
                                    "pattern": "^(?:(?:[\\w\\-\\.]+)|(?:\\$\\([\\w\\-\\.]+\\)))+$"
                                }
                            }
                        }
                    },
                    "account": {
                        "description": "AWS account to send the metric to. Typically $(nf.account)",
