    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "properties": {
        "etag": {
            "type": "string",
            "pattern": "^[\\w\\.:-]+$",
            "pbj": {
                "type": "string",
                "rule": "single"
            }
        },
        "css_class": {
            "type": "string",
            "pattern": "^[\\w\\s-]+$",
