    "type": "object",
    "properties": {
        "meta": {
            "type": "object",
            "properties": {
                "id": {
                    "type": "string",
                    "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"
                },
                "type": {
                    "type": "string",
                    "enum": [
                        "EiffelActivityStartedEvent"
                    ]
                },
                "version": {
                    "type": "string",
                    "enum": [
                        "3.0.0"
                    ],
                    "default": "3.0.0"
                },
                "time": {
                    "type": "integer"
                },
                "tags": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "source": {
                    "type": "object",
                    "properties": {
                        "domainId": {
                            "type": "string"
                        },
                        "host": {
                            "type": "string"
                        },
                        "name": {
                            "type": "string"
                        },
                        "serializer": {
                            "type": "string",
                            "pattern": "^pkg:"
                        },
                        "uri": {
                            "type": "string"
                        }
                    },
                    "additionalProperties": false
                },
                "security": {
                    "type": "object",
                    "properties": {
                        "sdm": {
                            "type": "object",
                            "properties": {
                                "authorIdentity": {
                                    "type": "string"
                                },
                                "encryptedDigest": {
                                    "type": "string"
                                }
                            },
                            "required": [
                                "authorIdentity",
                                "encryptedDigest"
                            ],
                            "additionalProperties": false
                        }
                    },
                    "additionalProperties": false
                }
            },
            "required": [
                "id",
                "type",
                "version",
                "time"
            ],
            "additionalProperties": false
        },
        "data": {
            "type": "object",
            "properties": {
                "executionUri": {
                    "type": "string"
                },
                "liveLogs": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "name": {
                                "type": "string"
                            },
                            "uri": {
                                "type": "string"
                            }
                        },
                        "required": [
                            "name",
                            "uri"
                        ],
                        "additionalProperties": false
                    }
                },
                "customData": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "key": {
                                "type": "string"
                            },
                            "value": {}
                        },
                        "required": [
                            "key",
                            "value"
                        ],
                        "additionalProperties": false
                    }
                }
            },
            "additionalProperties": false
        },
        "links": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "type": {
                        "type": "string"
                    },
                    "target": {
                        "type": "string",
                        "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"
                    }
                },
                "required": [
                    "type",
                    "target"
                ],
                "additionalProperties": false
            }
        }
    },
    "required": [
        "meta",
        "data",
        "links"
    ],
    "additionalProperties": false
}

