                        "ALERT",
                        "CRITICAL",
                        "ERROR",
                        "WARNING",
                        "NOTICE",
                        "INFO",
                        "DEBUG"
                    ]
                },
                "network": {
                    "description": "(OPTIONAL) Network type used by the Syslog",
                    "type": "string",
                    "default": "",
                    "enum": [
                        "",
                        "udp",
                        "tcp"
                    ]
                },
                "address": {
                    "description": "(OPTIONAL) Network address of the Syslog daemon (ip:port) or just (:port)",
                    "type": "string",
                    "default": ""
