        },
        "^SHA-512$": {
            "type": "string",
            "description": "Specifies the SHA-\u00ad512 cryptographic hash function (part of the SHA\u00ad2 family).",
            "pattern": "^[a-fA-F0-9]{128}$"
        },
        "^SHA3-224$": {
            "type": "string",
            "description": "Specifies the SHA3-224 cryptographic hash function.",
            "pattern": "^[a-fA-F0-9]{56}$"
        },
        "^SHA3-256$": {
            "type": "string",
