                            },
                            "required": [
                                "name",
                                "type"
                            ],
                            "type": "object"
                        },
                        "minItems": 1,
                        "type": "array"
                    },
                    "name": {
                        "pattern": "^[a-zA-Z_][a-zA-Z0-9_]*$",
                        "type": "string"
                    }
                },
                "required": [
                    "name",
                    "columns"
                ],
                "type": "object"
            },
            "minItems": 1,
            "type": "array"
        }
    },
    "required": [
        "tables",
        "inputs"
    ],
    "type": "object"
}

