                    "default": "content",
                    "format": "topic"
                }
            }
        },
        "show": {
            "type": "object",
            "description": "Show the content area upon action request.",
            "properties": {
                "onActions": {
                    "type": "array",
                    "description": "Actions on which the content should become visible.",
                    "items": {
                        "type": "string",
                        "format": "topic",
                        "axRole": "inlet"
                    }
                }
            }
        },
        "hide": {
            "type": "object",
